<?php declare(strict_types=1);namespace App\Core;final class Migrator{public function __construct(private string $dir=TP_ROOT.'/migrations'){}private function ensureTable():void{$k=new Schema(DB::driver(),'');$k->create(DB::table('migrations'),['id'=>'id','name'=>'string(191) unique','applied_at'=>'datetime']);foreach($k->statements()as $d){DB::pdo()->exec($d);}}public function applied():array{$this->ensureTable();return array_column(DB::fetchAll('SELECT name FROM '.DB::q(DB::table('migrations')).' ORDER BY name'),'name');}public function pending():array{$q=$this->applied();$i=glob($this->dir.'/*.php')?:[];sort($i);$K=[];foreach($i as $a){$C=basename($a,'.php');if(!in_array($C,$q,true)){$K[$C]=$a;}}return $K;}public function migrate(?callable $out=null):array{$done=[];foreach($this->pending()as $name=>$file){$def=require $file;$schema=new Schema(DB::driver(),(string)Config::get('db.prefix',''));if(is_callable($def)){$def($schema);}DB::transaction(function()use($schema,$name){foreach($schema->statements()as $sql){DB::pdo()->exec($sql);}DB::insert('migrations',['name'=>$name,'applied_at'=>now()]);});$done[]=$name;if($out){$out($name);}}return $done;}public function dump(string $driver):string{$out="-- ToutPVR — schéma {$driver} généré le ".gmdate('c')."\n";foreach(glob($this->dir.'/*.php')?:[]as $f){$def=require $f;$schema=new Schema($driver,(string)Config::get('db.prefix',''));$def($schema);$out.="\n-- ".basename($f)."\n";foreach($schema->statements()as $sql){$out.=$sql.";\n";}}return $out;}}